node -e '
const fs = require("fs");
const html = fs.readFileSync("index.html", "utf8");
const m = html.match(/<script>([\s\S]*?)<\/script>/);
if (!m) throw new Error("No script tag");
const code = m[1];
// Syntax check
new Function(code);
console.log("JS syntax OK");

// Extract ELEMENTS and RAW_RECIPES by evaluating the data section
const dataPart = code.slice(code.indexOf("const CATEGORIES"), code.indexOf("const RECIPE_MAP"));
const extracted = new Function(dataPart + "; return { ELEMENTS, RAW_RECIPES };")();
const { ELEMENTS, RAW_RECIPES } = extracted;

const allIds = Object.keys(ELEMENTS);
const starters = allIds.filter(id => ELEMENTS[id].starter);
console.log("Total elements:", allIds.length, "Starters:", starters);

const recipeKey = (a, b) => (a < b ? `${a}+${b}` : `${b}+${a}`);
const map = new Map();
const invalid = [];
const dupes = [];

for (const [a, b, res] of RAW_RECIPES) {
  if (!ELEMENTS[a] || !ELEMENTS[b] || !ELEMENTS[res]) {
    invalid.push([a, b, res]);
    continue;
  }
  const k = recipeKey(a, b);
  if (map.has(k)) {
    dupes.push({ k, prev: map.get(k), next: res });
  } else {
    map.set(k, res);
  }
}

console.log("Valid unique recipes:", map.size);
console.log("Invalid recipes:", invalid);
console.log("Duplicate keys:", dupes);

// BFS reachability from starters using ONLY RECIPE_MAP
const reached = new Set(starters);
let changed = true;
let rounds = 0;
while (changed) {
  changed = false;
  rounds++;
  for (const [k, res] of map.entries()) {
    const [a, b] = k.split("+");
    if (reached.has(a) && reached.has(b) && !reached.has(res)) {
      reached.add(res);
      changed = true;
    }
  }
}

const unreachable = allIds.filter(id => !reached.has(id));
console.log("Reached:", reached.size, "/", allIds.length, "in", rounds, "rounds");
console.log("Unreachable:", unreachable);

// Check category counts & legendaries
const byCat = {};
const byRarity = {};
for (const id of allIds) {
  byCat[ELEMENTS[id].cat] = (byCat[ELEMENTS[id].cat] || 0) + 1;
  byRarity[ELEMENTS[id].rarity] = (byRarity[ELEMENTS[id].rarity] || 0) + 1;
}
console.log("By category:", byCat);
console.log("By rarity:", byRarity);
'

